async () => {
  try {
    const text = await navigator.clipboard.readText();
    return { clipboard: text };
  } catch(e) {
    return { error: e.message };
  }
}

() => {
  // Find the URL in the share dialog
  const spans = document.querySelectorAll('span, input, a');
  const results = [];
  for (const el of spans) {
    const text = el.textContent || el.value || el.href || '';
    if (text.includes('goo.gl') || text.includes('google.com/maps') || text.includes('maps.app')) {
      results.push({tag: el.tagName, text: text.substring(0, 200), href: el.href || ''});
    }
  }
  return results;
}

() => {
  // Search for the URL in all elements
  const all = document.querySelectorAll('*');
  const results = [];
  for (const el of all) {
    const text = (el.textContent || '').trim();
    if (text.startsWith('https://maps.app.goo.gl/') || text.startsWith('http://maps.app.goo.gl/')) {
      results.push({tag: el.tagName, class: el.className, text: text});
    }
    // Also check data attributes
    for (const attr of el.attributes || []) {
      if (attr.value && (attr.value.includes('maps.app.goo.gl/') || attr.value.includes('google.com/maps'))) {
        results.push({tag: el.tagName, attr: attr.name, value: attr.value.substring(0, 200)});
      }
    }
  }
  return results.slice(0, 20);
}

async () => {
  try {
    const text = await navigator.clipboard.readText();
    return JSON.stringify({clipboard: text, length: text.length});
  } catch(e) {
    return JSON.stringify({error: e.message, name: e.name});
  }
}

() => {
  // Look for the share URL in inputs and data attributes
  const inputs = document.querySelectorAll('input');
  const inputInfo = [];
  for (const inp of inputs) {
    inputInfo.push({type: inp.type, value: inp.value, name: inp.name, id: inp.id});
  }

  // Look for elements with data-copy-text or similar attributes
  const copyEls = document.querySelectorAll('[data-copy-text], [data-share-url], [data-url]');
  const copyInfo = [];
  for (const el of copyEls) {
    copyInfo.push({tag: el.tagName, attrs: Array.from(el.attributes).map(a => `${a.name}=${a.value.substring(0,100)}`)});
  }

  // Look for the dialog content
  const dialog = document.querySelector('[role="dialog"], .share-dialog, [aria-label*="分享"]');
  let dialogText = '';
  if (dialog) {
    dialogText = dialog.textContent.substring(0, 500);
  }

  return JSON.stringify({inputs: inputInfo, copyEls: copyInfo, dialogText: dialogText}, null, 2);
}

() => {
  // Find all elements containing share URL info
  const results = __find("maps\\.app\\.goo\\.gl|google\\.com/maps");
  return results.map(el => ({
    index: el.index,
    tag: el.tagName,
    text: el.textContent ? el.textContent.substring(0, 200) : '',
    attrs: el.attrs
  }));
}

async () => {
  try {
    const text = await navigator.clipboard.readText();
    return text;
  } catch(e) {
    return 'Error: ' + e.message;
  }
}

async () => {
  // Try to read clipboard with fallback
  let result = {};
  try {
    result.clipboard = await navigator.clipboard.readText();
  } catch(e) {
    result.clipboardError = e.message;
  }

  // Also check if there's a share URL in any data attribute or variable
  const shareBtn = document.querySelector('#app-container-Copy Link, #app-container-Copied');
  if (shareBtn) {
    result.btnText = shareBtn.textContent;
    const parent = shareBtn.closest('[role="dialog"], div');
    if (parent) {
      result.parentHTML = parent.innerHTML.substring(0, 2000);
    }
  }

  // Check for any input with the URL
  const inputs = document.querySelectorAll('input[type="text"], input[type="url"], input[readonly]');
  result.inputs = [];
  for (const inp of inputs) {
    result.inputs.push({value: inp.value, type: inp.type, name: inp.name});
  }

  // Look for the URL in the entire dialog
  const dialog = document.querySelector('[aria-label*="Share"], [aria-label*="分享"]');
  if (dialog) {
    result.dialogHTML = dialog.outerHTML.substring(0, 3000);
  }

  return result;
}

() => {
  // Focus the search input and try to paste
  const input = document.querySelector('input[name="q"]');
  if (input) {
    input.focus();
    return 'focused';
  }
  return 'not found';
}

() => {
  const results = __find("maps\\.app\\.goo\\.gl");
  return results.map(el => ({
    tag: el.tagName,
    text: el.textContent ? el.textContent.substring(0, 500) : '',
    html: el.innerHTML ? el.innerHTML.substring(0, 500) : ''
  }));
}

() => {
  // Try to find the share URL in window properties
  const url = window.location.href;
  // Also try to find any global state with the share URL
  let keys = Object.keys(window).filter(k => k.includes('map') || k.includes('share') || k.includes('app'));
  return { url: url, keys: keys.slice(0, 20) };
}

async () => {
  // Create a temporary textarea and paste clipboard content
  const textarea = document.createElement('textarea');
  textarea.style.position = 'fixed';
  textarea.style.opacity = '0';
  textarea.style.left = '-9999px';
  document.body.appendChild(textarea);
  textarea.focus();

  let result = '';
  try {
    document.execCommand('paste');
    result = textarea.value;
  } catch(e) {
    result = 'execCommand error: ' + e.message;
  }

  document.body.removeChild(textarea);
  return result;
}

() => {
  // Google Maps stores app state in window.APP_OPTIONS or similar
  // Let's look for the share URL in the page's internal state
  const result = {};

  // Check window properties
  for (const key of Object.keys(window)) {
    if (key.includes('APP') || key.includes('INIT') || key.includes('STATE') || key.includes('CONFIG')) {
      try {
        const val = window[key];
        if (typeof val === 'string' && val.includes('maps.app.goo.gl')) {
          result[key] = val.substring(0, 500);
        } else if (typeof val === 'object' && val !== null) {
          const str = JSON.stringify(val);
          if (str.includes('maps.app.goo.gl')) {
            result[key] = str.substring(0, 500);
          }
        }
      } catch(e) {}
    }
  }

  return result;
}
